budget.value:
fun p =>
  have c := if h : ∃ t, 0 ≤ t ∧ ∑ i, min (p.L i) (t * ↑(p.h i)) = ↑↑p.n * p.μ then h.choose else 0;
  have u := fun i => min (p.L i) (c * ↑(p.h i));
  have S := ∑ i, u i / ↑(p.h i) * u i;
  have M := Finset.univ.sup' ⋯ fun i => u i * p.L i;
  have A := (2 * ∑ i, (↑(p.h i))⁻¹) * M / S;
  have w := ⌈2 + ↑p.d + A + (p.R ^ 2 + (p.σ * Finset.univ.sup' ⋯ u / M) ^ 2) / p.ε⌉₊.size;
  (2048 *
      (p.σ ^ 2 / (S * p.ε) +
        A * (1 + Real.log (1 + p.R ^ 2 / p.ε)) *
          (↑(Finset.univ.sup p.h) + ↑p.l + ↑p.b * (64 + 1024 * ↑p.d * ↑w)))).toNNReal

